def add(n,title,claims,as_he,plausible,state,why,worth,refs):
 ids=[f'C-SA14-{i:03}' for i in claims]
 occ=[{'claim':i,'cote':C[i]['cote'],'scans':C[i]['scans'],'lines':C[i]['lines']} for i in ids]
